function animate(el,frames,duration=430,options={}){if(!el||reduced())return Promise.resolve();return el.animate(frames,{duration,easing:'cubic-bezier(.2,.8,.2,1)',...options}).finished.catch(()=>{})}
function changeBody(html){const body=$('.focus-body');body.innerHTML=html;const input=$('#chat-form textarea');if(input&&focus)input.value=drafts.get(focus.type+':'+focus.id+':'+focus.tab)||'';animate(body,[{opacity:0,transform:'translateY(8px)'},{opacity:1,transform:'translateY(0)'}],260);const log=$('.chat-log');if(log)log.scrollTop=log.scrollHeight}
